package com.crms.entity;import java.time.LocalDate;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;@Document("placement_drives") public class PlacementDrive{@Id private Long id;private String name;private String description;private LocalDate startDate,endDate;private boolean active=true;public Long getId(){return id;}public void setId(Long v){id=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public LocalDate getStartDate(){return startDate;}public void setStartDate(LocalDate v){startDate=v;}public LocalDate getEndDate(){return endDate;}public void setEndDate(LocalDate v){endDate=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}}
